package walkthrough

import (
	"encoding/json"
	"io/fs"
	"os"
	"path/filepath"
	"testing"

	"github.com/datatug/datatug-core/pkg/apicontract"
	"github.com/stretchr/testify/require"
)

// trainingPackageCorpus is the independent stage-1 package inventory corpus.
// Its expectations are authored by testdata/package-corpus-v1/generate.py from
// the owner tables, never generated by this implementation.
type trainingPackageCorpus struct {
	CorpusVersion string                  `json:"corpusVersion"`
	Vectors       []trainingPackageVector `json:"vectors"`
}

type trainingPackageVector struct {
	ID          string                   `json:"id"`
	Description string                   `json:"description"`
	Directory   string                   `json:"directory"`
	IndexPath   string                   `json:"indexPath"`
	Reference   trainingPackageReference `json:"reference"`
	Binding     trainingPackageWitness   `json:"binding"`
	Want        trainingPackageWant      `json:"want"`
}

type trainingPackageReference struct {
	ID       string `json:"id"`
	Revision string `json:"revision"`
	Path     string `json:"path"`
	SHA256   string `json:"sha256"`
	Bytes    string `json:"bytes"`
}

type trainingPackageWitness struct {
	Project           string             `json:"project"`
	ContentPin        trainingPackagePin `json:"contentPin"`
	DeclarationSHA256 string             `json:"declarationSha256"`
	NarrativeSHA256   string             `json:"narrativeSha256"`
	PackageSHA256     string             `json:"packageSha256"`
	ScenarioID        string             `json:"scenarioId"`
	ScenarioRevision  string             `json:"scenarioRevision"`
}

type trainingPackagePin struct {
	Kind   string `json:"kind"`
	Commit string `json:"commit"`
	SHA256 string `json:"sha256"`
}

type trainingPackageWant struct {
	Admitted         bool           `json:"admitted"`
	NewerClient      bool           `json:"newerClient"`
	Definition       map[string]any `json:"definition"`
	DefinitionSHA256 string         `json:"definitionSha256"`
	Issues           []corpusIssue  `json:"issues"`
}

type trainingPackageProvenance struct {
	CorpusVersion   string            `json:"corpusVersion"`
	CorpusSHA256    string            `json:"corpusSha256"`
	GeneratorSHA256 string            `json:"generatorSha256"`
	VerifierSHA256  string            `json:"verifierSha256"`
	Files           map[string]string `json:"files"`
	FileBytes       map[string]int64  `json:"fileBytes"`
}

const trainingPackageCorpusDir = "package-corpus-v1"

func loadTrainingPackageCorpus(t *testing.T) trainingPackageCorpus {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", trainingPackageCorpusDir, "corpus.json"))
	require.NoError(t, err)
	var corpus trainingPackageCorpus
	require.NoError(t, apicontract.DecodeStrict(raw, &corpus))
	require.Equal(t, "training-package-corpus-v1", corpus.CorpusVersion)
	require.NotEmpty(t, corpus.Vectors)
	seen := make(map[string]bool, len(corpus.Vectors))
	for _, vector := range corpus.Vectors {
		require.NotEmpty(t, vector.ID)
		require.NotEmpty(t, vector.Description)
		require.NotEmpty(t, vector.Directory)
		require.NotEmpty(t, vector.IndexPath)
		require.False(t, seen[vector.ID], "duplicate vector id %q", vector.ID)
		seen[vector.ID] = true
	}
	return corpus
}

func trainingPackageInputFor(t *testing.T, vector trainingPackageVector) TrainingPackageInput {
	t.Helper()
	caseDir := filepath.Join("testdata", trainingPackageCorpusDir, "cases", vector.Directory)
	indexBytes, err := os.ReadFile(filepath.Join(caseDir, filepath.FromSlash(vector.IndexPath)))
	require.NoError(t, err)
	require.Equal(t, vector.Reference.SHA256, sha256Hex(indexBytes))
	require.Equal(t, vector.Reference.Bytes, itoa(int64(len(indexBytes))))
	assets := make([]TrainingPackageAssetBytes, 0)
	err = filepath.WalkDir(caseDir, func(path string, entry fs.DirEntry, walkErr error) error {
		require.NoError(t, walkErr)
		if entry.IsDir() {
			return nil
		}
		relative, relativeErr := filepath.Rel(caseDir, path)
		require.NoError(t, relativeErr)
		relative = filepath.ToSlash(relative)
		if relative == vector.IndexPath {
			return nil
		}
		data, readErr := os.ReadFile(path)
		require.NoError(t, readErr)
		assets = append(assets, TrainingPackageAssetBytes{Path: relative, Bytes: data})
		return nil
	})
	require.NoError(t, err)
	project := ProjectIdentity{}
	if vector.Binding.Project != "" {
		project.Value = vector.Binding.Project
	}
	pin := ContentPin{Kind: vector.Binding.ContentPin.Kind}
	switch pin.Kind {
	case PinGit:
		pin.Commit = vector.Binding.ContentPin.Commit
	case PinDigest:
		pin.SHA256 = vector.Binding.ContentPin.SHA256
	}
	return TrainingPackageInput{
		Reference: PackageReference{
			ID:       vector.Reference.ID,
			Revision: Integer(vector.Reference.Revision),
			Path:     vector.Reference.Path,
			SHA256:   vector.Reference.SHA256,
			Bytes:    Integer(vector.Reference.Bytes),
		},
		IndexBytes: indexBytes,
		Assets:     assets,
		Binding: TrainingPackageBinding{
			Project:           project,
			ContentPin:        pin,
			DeclarationSHA256: vector.Binding.DeclarationSHA256,
			NarrativeSHA256:   vector.Binding.NarrativeSHA256,
			PackageSHA256:     vector.Binding.PackageSHA256,
			ScenarioID:        vector.Binding.ScenarioID,
			ScenarioRevision:  Integer(vector.Binding.ScenarioRevision),
		},
	}
}

func TestTrainingPackageCorpus(t *testing.T) {
	corpus := loadTrainingPackageCorpus(t)
	for _, vector := range corpus.Vectors {
		vector := vector
		t.Run(vector.ID, func(t *testing.T) {
			result := AdmitTrainingPackage(trainingPackageInputFor(t, vector))
			require.Equal(t, vector.Want.Admitted, result.Admitted, "issues: %v", result.Issues)
			require.Equal(t, vector.Want.NewerClient, result.NewerClient)
			if vector.Want.Admitted {
				require.NoError(t, result.Err())
				require.NotNil(t, result.Package)
				projection := jsonPlain(t, result.Package.Projection())
				if vector.Want.Definition != nil {
					require.Equal(t, vector.Want.Definition, projection)
				}
				if vector.Want.DefinitionSHA256 != "" {
					raw, err := json.Marshal(projection)
					require.NoError(t, err)
					require.Equal(t, vector.Want.DefinitionSHA256, sha256Hex(raw))
				}
				return
			}
			require.Nil(t, result.Package, "a refused package must not expose a partial snapshot")
			if vector.Want.NewerClient {
				require.Empty(t, result.Issues)
				require.ErrorIs(t, result.Err(), ErrNewerTrainingPackage)
				return
			}
			require.Error(t, result.Err())
			require.Equal(t, vector.Want.Issues, corpusIssues(result.Issues))
		})
	}
}

func TestTrainingPackageCorpusProvenance(t *testing.T) {
	root := filepath.Join("testdata", trainingPackageCorpusDir)
	raw, err := os.ReadFile(filepath.Join(root, "corpus.json"))
	require.NoError(t, err)
	provenanceRaw, err := os.ReadFile(filepath.Join(root, "provenance.json"))
	require.NoError(t, err)
	var provenance trainingPackageProvenance
	require.NoError(t, apicontract.DecodeStrict(provenanceRaw, &provenance))
	require.Equal(t, "training-package-corpus-v1", provenance.CorpusVersion)
	require.Equal(t, sha256Hex(raw), provenance.CorpusSHA256)
	require.NotEmpty(t, provenance.Files)
	require.Equal(t, len(provenance.Files), len(provenance.FileBytes))
	for _, source := range []struct {
		name string
		hash string
	}{{"generate.py", provenance.GeneratorSHA256}, {"verify.py", provenance.VerifierSHA256}} {
		data, err := os.ReadFile(filepath.Join(root, source.name))
		require.NoError(t, err)
		require.Equal(t, sha256Hex(data), source.hash, source.name)
	}
	for relative, expected := range provenance.Files {
		data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(relative)))
		require.NoError(t, err, relative)
		require.Equal(t, expected, sha256Hex(data), relative)
		require.Equal(t, int64(len(data)), provenance.FileBytes[relative], relative)
	}
}

// TestTrainingPackageCallerMutation proves the admitted snapshot neither
// aliases caller bytes nor changes when the caller edits its own buffers or a
// previously returned projection. It retains the original admitted object; it
// deliberately does not re-admit a fresh package from disk.
func TestTrainingPackageCallerMutation(t *testing.T) {
	input := corpusInput(t, "full")
	admitted := mustAdmit(t, input)
	before := jsonPlain(t, admitted.Projection())
	beforeTrusted := admitted.TrustedPackageInventory()
	beforeNarrative := admitted.TrustedNarrativeInventory()

	for index := range input.IndexBytes {
		input.IndexBytes[index] = 'x'
	}
	for index := range input.Assets {
		for byteIndex := range input.Assets[index].Bytes {
			input.Assets[index].Bytes[byteIndex] = 'y'
		}
	}
	require.Equal(t, before, jsonPlain(t, admitted.Projection()))

	// Complete and reduced projections are defensively rebuilt. Mutating a
	// returned value cannot rewrite the retained admitted object, and the next
	// projection from that same object is still the original one.
	projection := admitted.Projection()
	projection["id"] = "mutated"
	projection["assets"].([]any)[0].(map[string]any)["kind"] = "mutated"
	projection["codecs"].([]any)[0].(map[string]any)["text"] = "mutated"
	trusted := admitted.TrustedPackageInventory()
	trusted.Assets[0].Path = "mutated"
	trusted.Cases[0] = "mutated"
	narrative := admitted.TrustedNarrativeInventory()
	narrative.Assets[0].AssetID = "mutated"
	narrative.Cases[0] = "mutated"

	require.Equal(t, before, jsonPlain(t, admitted.Projection()))
	require.Equal(t, beforeTrusted, admitted.TrustedPackageInventory())
	require.Equal(t, beforeNarrative, admitted.TrustedNarrativeInventory())
}

func mustAdmit(t *testing.T, input TrainingPackageInput) *AdmittedTrainingPackage {
	t.Helper()
	result := AdmitTrainingPackage(input)
	require.True(t, result.Admitted, "issues: %v", result.Issues)
	require.NotNil(t, result.Package)
	return result.Package
}
